-- tenant scans / export

-- Membership. role_kind codes PROVEN: 1 owner, 2 admin, 3 member, 4 guest.
-- guest_subtype PROVEN as 4 values (order not tied to numbers, so stored as text).
CREATE TABLE workspace_members (
  id              uuid PRIMARY KEY,
  workspace_id    uuid NOT NULL REFERENCES workspaces(id),
  user_id         uuid NOT NULL /* id -> identity.users */,
  role_kind       text NOT NULL CHECK (role_kind IN ('owner','admin','member','guest')),
  guest_subtype   text CHECK (guest_subtype IN ('external_read_only','external','limited_member_read_only','limited_member')),
  custom_role_id  uuid REFERENCES roles(id),           -- optional custom workspace role refining 'member'. ASSUMED
  status          text NOT NULL DEFAULT 'active' CHECK (status IN ('active','pending','deactivated')), -- PROVEN "Pending"; others ASSUMED
  invited_by      uuid /* id -> identity.users */,           -- PROVEN
  invited_at      timestamptz,                         -- PROVEN date_invited
  joined_at       timestamptz,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  deleted_at      timestamptz,
  version         integer NOT NULL DEFAULT 1,
  CHECK (guest_subtype IS NULL OR role_kind = 'guest')
);

