-- =============================================================================
-- 4. PEOPLE FIELDS and billable defaults  (captured 6 Nov 2026, see plan/captures-cost-time.md)
-- PROVEN in the ClickUp UI: Settings > People > column chooser > "Custom Fields on People" (Business Plus). Field types listed:
-- text, number, currency, date, dropdown, label, URI. Suggested fields: Skills, Job Role, About me, Languages. Access can be limited by role/group.
-- The client most likely keeps each person's hourly amount in such a field. We could NOT create one (plan locked), so the
-- storage shape below is our design. A tenant defines its own fields, nothing is fixed per company.
-- =============================================================================
CREATE TABLE people_field_defs (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  name text NOT NULL,
  description text,
  field_type text NOT NULL CHECK (field_type IN ('short_text','long_text','number','currency','date','dropdown','labels','url')),
  type_config jsonb NOT NULL DEFAULT '{}',                  -- currency code, precision, etc.
  shown_in_table boolean NOT NULL DEFAULT true,
  position text NOT NULL COLLATE "C",
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1
);

CREATE UNIQUE INDEX people_field_defs_name_uk ON people_field_defs (workspace_id, lower(name)) WHERE deleted_at IS NULL;

CREATE TABLE people_field_options (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  field_id uuid NOT NULL REFERENCES people_field_defs(id) ON DELETE CASCADE,
  label text NOT NULL, color text, position text NOT NULL COLLATE "C"
);

CREATE TABLE people_field_values (
  workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  user_id uuid NOT NULL /* id -> identity.users */,
  field_id uuid NOT NULL REFERENCES people_field_defs(id) ON DELETE CASCADE,
  text_value text,
  number_value numeric(20,6),
  money_cents bigint, money_currency char(3),
  date_value date,
  option_ids uuid[],                                        -- dropdown (one) or labels (many)
  updated_by uuid /* id -> identity.users */,
  updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1,
  PRIMARY KEY (workspace_id, user_id, field_id),
  CHECK ((text_value IS NOT NULL)::int + (number_value IS NOT NULL)::int + (money_cents IS NOT NULL)::int
       + (date_value IS NOT NULL)::int + (option_ids IS NOT NULL)::int <= 1),
  CHECK ((money_cents IS NULL) = (money_currency IS NULL))
);

-- who may see or set a field: role or group, same idea as custom_field_access
CREATE TABLE people_field_access (
  workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  field_id uuid NOT NULL REFERENCES people_field_defs(id) ON DELETE CASCADE,
  role_id uuid REFERENCES roles(id), group_id uuid REFERENCES user_groups(id),
  can_edit boolean NOT NULL DEFAULT false,
  CHECK ((role_id IS NULL) <> (group_id IS NULL))
);

-- NULL = inherit (space, then workspace)
ALTER TABLE workspaces ADD COLUMN time_default_billable boolean NOT NULL DEFAULT false;

INSERT INTO capabilities (key, description, scope) VALUES
  ('manage_people_fields','define people fields and set their values for others','workspace'),
  ('view_people_fields','see people fields that are not restricted','workspace');

-- ===== NEW for the split (plan/tech/04-permissions-spec.md)

-- Copy of the container tree, kept from hierarchy container.* events. The permission engine walks it.
CREATE TABLE container_tree (
  container_id    uuid PRIMARY KEY,
  workspace_id    uuid NOT NULL REFERENCES workspaces(id),
  kind            text NOT NULL CHECK (kind IN ('space','folder','list')),
  parent_id       uuid,
  ancestor_ids    uuid[] NOT NULL,                   -- root first, including self
  is_restricted   boolean NOT NULL DEFAULT false,
  archived        boolean NOT NULL DEFAULT false,
  deleted         boolean NOT NULL DEFAULT false,
  source_version  integer NOT NULL,
  updated_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX container_tree_ws_idx ON container_tree (workspace_id);

-- One counter per workspace, bumped by every change that can alter an answer (grant, role, member, group,
-- tree). It is part of every permission cache key, so a bump makes all cached answers of that workspace stale.
CREATE TABLE access_epochs (
  workspace_id    uuid PRIMARY KEY REFERENCES workspaces(id),
  epoch           bigint NOT NULL DEFAULT 1,
  updated_at      timestamptz NOT NULL DEFAULT now()
);


-- ===== _epilogue.sql =====
-- Loaded LAST into every service database (hand-written, not generated).
-- 1) version trigger on every table that has version + updated_at
-- 2) row-level security on every table with a NOT NULL workspace_id (plan/tech/09-security.md)
-- Contract: through PgBouncer in transaction mode, every transaction starts with
--   SELECT set_config('app.workspace_id', '<uuid>', true);   -- true = this transaction only
-- A session-level SET would leak to the next client of the pooled connection, so it is forbidden.

DO $$
DECLARE r record;
BEGIN
  FOR r IN
    SELECT c.table_name
    FROM information_schema.columns c
    JOIN information_schema.columns v ON v.table_schema = c.table_schema AND v.table_name = c.table_name AND v.column_name = 'updated_at'
    JOIN information_schema.tables t ON t.table_schema = c.table_schema AND t.table_name = c.table_name AND t.table_type = 'BASE TABLE'
    WHERE c.table_schema = current_schema() AND c.column_name = 'version'
      AND NOT EXISTS (SELECT 1 FROM pg_trigger g WHERE g.tgrelid = (quote_ident(c.table_name))::regclass AND g.tgname = c.table_name || '_bump_version')
  LOOP
    EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION bump_version()',
                   r.table_name || '_bump_version', r.table_name);
  END LOOP;
END $$;

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_user') THEN CREATE ROLE app_user NOLOGIN; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_worker') THEN CREATE ROLE app_worker NOLOGIN BYPASSRLS; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_migrator') THEN CREATE ROLE app_migrator NOLOGIN; END IF;
END $$;

DO $$
DECLARE t record;
BEGIN
  FOR t IN
    SELECT c.relname
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace AND n.nspname = current_schema()
      JOIN pg_attribute a ON a.attrelid = c.oid AND a.attname = 'workspace_id' AND NOT a.attisdropped
     WHERE c.relkind IN ('r','p') AND NOT c.relispartition AND a.attnotnull
       AND c.relname NOT IN ('outbox','inbox')        -- written by the app, read only by Debezium / the consumer itself
       AND coalesce(obj_description(c.oid, 'pg_class'), '') NOT LIKE 'rls:exempt%'   -- global services mark routing tables
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t.relname);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t.relname);
    EXECUTE format('DROP POLICY IF EXISTS workspace_isolation ON %I', t.relname);
    EXECUTE format('CREATE POLICY workspace_isolation ON %I USING (workspace_id = current_workspace()) WITH CHECK (workspace_id = current_workspace())', t.relname);
  END LOOP;
END $$;

GRANT USAGE ON SCHEMA public TO app_user, app_worker;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO app_user, app_worker;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO app_user, app_worker;
-- Tables with a nullable workspace_id (built-in rows) are not covered above; services add their own policy.
-- hierarchy: status_templates (built-ins have NULL workspace_id)
DO $$ BEGIN
  IF to_regclass('status_templates') IS NOT NULL THEN
    EXECUTE 'ALTER TABLE status_templates ENABLE ROW LEVEL SECURITY';
    EXECUTE 'DROP POLICY IF EXISTS status_templates_read ON status_templates';
    EXECUTE 'DROP POLICY IF EXISTS status_templates_write ON status_templates';
    EXECUTE 'CREATE POLICY status_templates_read ON status_templates FOR SELECT USING (workspace_id IS NULL OR workspace_id = current_workspace())';
    EXECUTE 'CREATE POLICY status_templates_write ON status_templates FOR ALL USING (workspace_id = current_workspace()) WITH CHECK (workspace_id = current_workspace())';
  END IF;
  -- audit: append-only for the app roles
  IF to_regclass('audit_log') IS NOT NULL THEN
    EXECUTE 'REVOKE UPDATE, DELETE, TRUNCATE ON audit_log, security_events, data_access_log FROM app_user, app_worker';
  END IF;
END $$;

